                  <span class="choice-text">CSS</span>
                </label>
                <label class="choice">
                  <input type="checkbox" name="frontend-languages" value="ruby">
                  <span class="choice-text">Ruby</span>
                </label>
                <label class="choice">
                  <input type="checkbox" name="frontend-languages" value="typescript">
                  <span class="choice-text">TypeScript</span>
                </label>
              </div>
            </fieldset>
          </div>

          <div class="form-field">
            <fieldset>
              <legend>3. Which languages are known for systems programming?</legend>
              <div class="choices">
                <label class="choice">
                  <input type="checkbox" name="systems-languages" value="c">
                  <span class="choice-text">C</span>
                </label>
                <label class="choice">
                  <input type="checkbox" name="systems-languages" value="rust">
                  <span class="choice-text">Rust</span>
                </label>
                <label class="choice">
                  <input type="checkbox" name="systems-languages" value="go">
                  <span class="choice-text">Go</span>
                </label>
                <label class="choice">
                  <input type="checkbox" name="systems-languages" value="sql">
                  <span class="choice-text">SQL</span>
                </label>
              </div>
            </fieldset>
          </div>

          <div class="actions">
            <button type="submit">Submit quiz</button>
            <p class="result" id="quiz-result" aria-live="polite"></p>
