        </form>
      </section>
    </main>

    <footer>
      <p>Use Tab to move through answers and Space to check or uncheck each option.</p>
    </footer>

    <script>
      const quiz = document.querySelector("#language-quiz");
      const result = document.querySelector("#quiz-result");
      const questionNames = [
        "programming-languages",
        "frontend-languages",
        "systems-languages",
      ];

      quiz.addEventListener("submit", (event) => {
        event.preventDefault();

        const selectedCount = questionNames.reduce((total, name) => {
          return total + quiz.querySelectorAll(`input[name="${name}"]:checked`).length;
        }, 0);

        result.textContent =
          selectedCount === 1
            ? "Quiz submitted with 1 selected answer."
            : `Quiz submitted with ${selectedCount} selected answers.`;
        result.dataset.tone = "success";
      });
